<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$q=mb_substr(trim((string)($_GET['q']??'')),0,100);$type=$_GET['type']??'all';$allowed=['all','projects','news','events','members'];if(!in_array($type,$allowed,true))$type='all';$results=[];if($q!==''){$like='%'.$q.'%';if($type==='all'||$type==='projects'){$s=db()->prepare("SELECT id,'project' type,title_en title,description_en excerpt FROM projects WHERE title_en LIKE ? OR title_fr LIKE ? OR title_ar LIKE ? OR description_en LIKE ? OR category LIKE ? ORDER BY id DESC LIMIT 30");$s->execute([$like,$like,$like,$like,$like]);$results=array_merge($results,$s->fetchAll());}if($type==='all'||$type==='news'){$s=db()->prepare("SELECT id,'news' type,title_en title,body_en excerpt FROM news WHERE is_published=1 AND (title_en LIKE ? OR title_fr LIKE ? OR title_ar LIKE ? OR body_en LIKE ? OR category LIKE ?) ORDER BY published_at DESC LIMIT 30");$s->execute([$like,$like,$like,$like,$like]);$results=array_merge($results,$s->fetchAll());}if($type==='all'||$type==='events'){$s=db()->prepare("SELECT id,'event' type,title_en title,description_en excerpt FROM events WHERE is_published=1 AND (title_en LIKE ? OR title_fr LIKE ? OR title_ar LIKE ? OR description_en LIKE ? OR location LIKE ?) ORDER BY event_date DESC LIMIT 30");$s->execute([$like,$like,$like,$like,$like]);$results=array_merge($results,$s->fetchAll());}if(($type==='all'||$type==='members')&&currentUser()&&in_array((string)currentUser()['role'],['member','admin'],true)){$s=db()->prepare("SELECT id,'member' type,full_name title,bio excerpt FROM users WHERE role='member' AND is_active=1 AND is_banned=0 AND (full_name LIKE ? OR username LIKE ? OR occupation LIKE ? OR bio LIKE ?) ORDER BY full_name LIMIT 30");$s->execute([$like,$like,$like,$like]);$results=array_merge($results,$s->fetchAll());}}$pageTitle='Search';require __DIR__.'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Search</p><h1 class="section-title">Find content and members.</h1><form class="search-large" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search projects, news, events…" required><select name="type"><option value="all" <?=$type==='all'?'selected':''?>>All content</option><option value="projects" <?=$type==='projects'?'selected':''?>>Projects</option><option value="news" <?=$type==='news'?'selected':''?>>News</option><option value="events" <?=$type==='events'?'selected':''?>>Events</option><option value="members" <?=$type==='members'?'selected':''?>>Members</option></select><button class="btn primary">Search</button></form><?php if($q===''):?><p class="copy">Enter a term above to search.</p><?php elseif(!$results):?><p class="copy">No results found for “<?=e($q)?>”.</p><?php else:?><div class="grid-3" style="margin-top:35px"><?php foreach($results as $r):?><article class="card"><div class="card-body"><span class="tag"><?=e($r['type'])?></span><h3><?=e($r['title'])?></h3><p><?=e(mb_strimwidth(strip_tags((string)$r['excerpt']),0,180,'…'))?></p><?php if($r['type']==='project'):?><a class="btn primary" href="project-detail.php?id=<?=$r['id']?>">Open</a><?php elseif($r['type']==='news'):?><a class="btn primary" href="article.php?id=<?=$r['id']?>">Open</a><?php elseif($r['type']==='event'):?><a class="btn coral" href="event-detail.php?id=<?=$r['id']?>">Open</a><?php else:?><a class="btn ghost" href="member/view.php?id=<?=$r['id']?>">Member</a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';
